CREATE DATABASE IF NOT EXISTS restaurant_saas CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE restaurant_saas;
SET default_storage_engine=InnoDB;
-- Theme layout columns are added below, before sample data is inserted.
CREATE TABLE restaurants (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, slug VARCHAR(160) NOT NULL UNIQUE, description TEXT NULL, contact_email VARCHAR(190) NULL, contact_phone VARCHAR(40) NULL, address TEXT NULL, logo_path VARCHAR(255) NULL, banner_path VARCHAR(255) NULL, brand_color VARCHAR(20) NOT NULL DEFAULT '#174b3a', timezone VARCHAR(64) NOT NULL DEFAULT 'Asia/Colombo', service_charge_percent DECIMAL(5,2) NOT NULL DEFAULT 10.00, delivery_minimum DECIMAL(12,2) NOT NULL DEFAULT 1000.00, is_accepting_orders TINYINT(1) NOT NULL DEFAULT 1, online_ordering_enabled TINYINT(1) NOT NULL DEFAULT 1, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restaurant_id BIGINT UNSIGNED NULL, role ENUM('SUPER_ADMIN','RESTAURANT_ADMIN','CASHIER') NOT NULL, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, menu_item_add_enabled TINYINT(1) NOT NULL DEFAULT 1, menu_item_edit_enabled TINYINT(1) NOT NULL DEFAULT 1, menu_item_delete_enabled TINYINT(1) NOT NULL DEFAULT 1, category_add_enabled TINYINT(1) NOT NULL DEFAULT 1, category_delete_enabled TINYINT(1) NOT NULL DEFAULT 1, category_rename_enabled TINYINT(1) NOT NULL DEFAULT 1, cashier_dashboard_menu_permissions TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE);
CREATE TABLE restaurant_pos_settings (restaurant_id BIGINT UNSIGNED NOT NULL PRIMARY KEY, pos_enabled TINYINT(1) NOT NULL DEFAULT 0, manager_bill_edit_enabled TINYINT(1) NOT NULL DEFAULT 0, accepted_order_cancellation_enabled TINYINT(1) NOT NULL DEFAULT 0, receipt_width_mm TINYINT UNSIGNED NOT NULL DEFAULT 80, receipt_template TINYINT UNSIGNED NOT NULL DEFAULT 1, updated_by BIGINT UNSIGNED NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE, FOREIGN KEY (updated_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE subscriptions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restaurant_id BIGINT UNSIGNED NOT NULL, plan VARCHAR(80) DEFAULT 'Annual', fee DECIMAL(12,2) DEFAULT 0, currency CHAR(3) DEFAULT 'LKR', starts_on DATE NOT NULL, expires_on DATE NOT NULL, status ENUM('TRIAL','ACTIVE','EXPIRED','SUSPENDED') DEFAULT 'TRIAL', FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE, INDEX(restaurant_id,expires_on));
CREATE TABLE menu_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restaurant_id BIGINT UNSIGNED NOT NULL, name VARCHAR(100) NOT NULL, sort_order INT DEFAULT 0, image_path VARCHAR(255) NULL, bottom_image_path VARCHAR(255) NULL, FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE);
ALTER TABLE restaurants ADD COLUMN menu_layout TINYINT UNSIGNED NOT NULL DEFAULT 1;
ALTER TABLE restaurants ADD COLUMN menu_background_path VARCHAR(255) NULL;
CREATE TABLE menu_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restaurant_id BIGINT UNSIGNED NOT NULL, category_id BIGINT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, description TEXT NULL, price DECIMAL(12,2) NOT NULL, is_portioned TINYINT(1) NOT NULL DEFAULT 0, half_price DECIMAL(12,2) NULL, full_price DECIMAL(12,2) NULL, image_path VARCHAR(255) NULL, is_available TINYINT(1) NOT NULL DEFAULT 1, is_active TINYINT(1) NOT NULL DEFAULT 1, FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE, FOREIGN KEY (category_id) REFERENCES menu_categories(id) ON DELETE RESTRICT, INDEX(restaurant_id,is_available),INDEX(restaurant_id,is_active,category_id));
CREATE TABLE restaurant_tables (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restaurant_id BIGINT UNSIGNED NOT NULL, table_number VARCHAR(30) NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, token_cipher TEXT NULL, is_active TINYINT(1) DEFAULT 1, UNIQUE(restaurant_id,table_number), FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE);
CREATE TABLE restaurant_menu_visits (restaurant_id BIGINT UNSIGNED NOT NULL PRIMARY KEY, visit_count BIGINT UNSIGNED NOT NULL DEFAULT 0, last_visited_at DATETIME NULL, FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE);
CREATE TABLE dining_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restaurant_id BIGINT UNSIGNED NOT NULL, table_id BIGINT UNSIGNED NOT NULL, session_number VARCHAR(40) NOT NULL UNIQUE, client_token_hash CHAR(64) NOT NULL, status ENUM('ACTIVE','EXPIRED','CLOSED') NOT NULL DEFAULT 'ACTIVE', started_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, closed_at DATETIME NULL, KEY idx_dining_session_lookup (table_id,client_token_hash,status,expires_at), KEY idx_dining_session_expiry (status,expires_at), FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE, FOREIGN KEY (table_id) REFERENCES restaurant_tables(id) ON DELETE RESTRICT);
CREATE TABLE restaurant_customers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restaurant_id BIGINT UNSIGNED NOT NULL, name VARCHAR(120) NULL, phone VARCHAR(40) NOT NULL, address VARCHAR(500) NULL, origin ENUM('MANAGER','ONLINE_REGISTRATION','ONLINE_GUEST','POS','LEGACY') NOT NULL DEFAULT 'MANAGER', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY uq_customer_phone (restaurant_id,phone), FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE);
CREATE TABLE online_customer_accounts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restaurant_id BIGINT UNSIGNED NOT NULL, customer_id BIGINT UNSIGNED NOT NULL, email VARCHAR(190) NULL, password_hash VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY uq_online_account_customer (restaurant_id,customer_id), KEY idx_online_account_email (restaurant_id,email), FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE, FOREIGN KEY (customer_id) REFERENCES restaurant_customers(id) ON DELETE CASCADE);
CREATE TABLE online_customer_password_resets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restaurant_id BIGINT UNSIGNED NOT NULL, account_id BIGINT UNSIGNED NOT NULL, temp_password_hash VARCHAR(255) NOT NULL, attempts TINYINT UNSIGNED NOT NULL DEFAULT 0, requested_ip_hash CHAR(64) NOT NULL, created_at DATETIME NOT NULL, sent_at DATETIME NULL, expires_at DATETIME NOT NULL, used_at DATETIME NULL, KEY idx_customer_reset_account (restaurant_id,account_id,created_at), KEY idx_customer_reset_ip (requested_ip_hash,created_at), FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE, FOREIGN KEY (account_id) REFERENCES online_customer_accounts(id) ON DELETE CASCADE);
CREATE TABLE online_customer_addresses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restaurant_id BIGINT UNSIGNED NOT NULL, customer_id BIGINT UNSIGNED NOT NULL, label VARCHAR(80) NULL, address VARCHAR(500) NOT NULL, address_hash CHAR(64) NOT NULL, is_default TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY uq_online_customer_address (restaurant_id,customer_id,address_hash), INDEX idx_online_customer_addresses (restaurant_id,customer_id,is_default,id), FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE, FOREIGN KEY (customer_id) REFERENCES restaurant_customers(id) ON DELETE CASCADE);
CREATE TABLE orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restaurant_id BIGINT UNSIGNED NOT NULL, table_id BIGINT UNSIGNED NULL, dining_session_id BIGINT UNSIGNED NULL, customer_id BIGINT UNSIGNED NULL, order_number VARCHAR(30) NOT NULL, special_request TEXT NULL, total DECIMAL(12,2) NOT NULL, status ENUM('PENDING','ACCEPTED','PREPARING','READY','SERVED','REJECTED','COMPLETED','CANCELLED') NOT NULL DEFAULT 'PENDING', idempotency_key CHAR(64) NOT NULL, source ENUM('QR','POS') NOT NULL DEFAULT 'QR', order_type ENUM('DINE_IN','TAKEAWAY','DELIVERY') NOT NULL DEFAULT 'DINE_IN', customer_name VARCHAR(120) NULL, customer_phone VARCHAR(40) NULL, delivery_address VARCHAR(500) NULL, delivery_notes VARCHAR(500) NULL, online_payment_method ENUM('CASH_ON_DELIVERY','PAY_AT_PICKUP','ONLINE_PAYMENT') NULL, packaging_charge DECIMAL(12,2) NOT NULL DEFAULT 0, delivery_charge DECIMAL(12,2) NOT NULL DEFAULT 0, guest_count SMALLINT UNSIGNED NULL, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE(restaurant_id,idempotency_key), UNIQUE KEY uq_orders_restaurant_order_number (restaurant_id,order_number), FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE, FOREIGN KEY (table_id) REFERENCES restaurant_tables(id) ON DELETE RESTRICT, FOREIGN KEY (dining_session_id) REFERENCES dining_sessions(id) ON DELETE RESTRICT, FOREIGN KEY (customer_id) REFERENCES restaurant_customers(id) ON DELETE SET NULL, INDEX(restaurant_id,status,created_at), INDEX(dining_session_id,created_at));
CREATE TABLE menu_item_options (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restaurant_id BIGINT UNSIGNED NOT NULL, menu_item_id BIGINT UNSIGNED NOT NULL, name VARCHAR(40) NOT NULL, price DECIMAL(12,2) NOT NULL, sort_order TINYINT UNSIGNED NOT NULL DEFAULT 0, is_default TINYINT(1) NOT NULL DEFAULT 0, UNIQUE KEY uq_menu_option_name (menu_item_id,name), KEY ix_menu_option_restaurant (restaurant_id,menu_item_id), FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE, FOREIGN KEY (menu_item_id) REFERENCES menu_items(id) ON DELETE CASCADE);
CREATE TABLE order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, menu_item_id BIGINT UNSIGNED NOT NULL, item_name VARCHAR(150) NOT NULL, portion VARCHAR(50) NULL, unit_price DECIMAL(12,2) NOT NULL, quantity INT NOT NULL, subtotal DECIMAL(12,2) NOT NULL, special_instruction VARCHAR(500) NULL, FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY (menu_item_id) REFERENCES menu_items(id));
CREATE TABLE pos_invoices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restaurant_id BIGINT UNSIGNED NOT NULL, order_id BIGINT UNSIGNED NOT NULL, invoice_number VARCHAR(40) NOT NULL, subtotal DECIMAL(12,2) NOT NULL, discount DECIMAL(12,2) NOT NULL DEFAULT 0, service_charge DECIMAL(12,2) NOT NULL DEFAULT 0, tax DECIMAL(12,2) NOT NULL DEFAULT 0, packaging_charge DECIMAL(12,2) NOT NULL DEFAULT 0, delivery_charge DECIMAL(12,2) NOT NULL DEFAULT 0, total DECIMAL(12,2) NOT NULL, paid_total DECIMAL(12,2) NOT NULL DEFAULT 0, payment_status ENUM('UNPAID','PARTIALLY_PAID','PAID') NOT NULL DEFAULT 'UNPAID', generated_by BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY uq_pos_invoice_order (restaurant_id,order_id), UNIQUE KEY uq_pos_invoice_number (restaurant_id,invoice_number), KEY idx_pos_invoice_date (restaurant_id,created_at), FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE, FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY (generated_by) REFERENCES users(id) ON DELETE RESTRICT);
CREATE TABLE pos_invoice_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invoice_id BIGINT UNSIGNED NOT NULL, order_item_id BIGINT UNSIGNED NULL, menu_item_id BIGINT UNSIGNED NULL, item_name VARCHAR(150) NOT NULL, portion VARCHAR(50) NULL, quantity INT UNSIGNED NOT NULL, unit_price DECIMAL(12,2) NOT NULL, discount DECIMAL(12,2) NOT NULL DEFAULT 0, line_total DECIMAL(12,2) NOT NULL, special_instruction VARCHAR(500) NULL, FOREIGN KEY (invoice_id) REFERENCES pos_invoices(id) ON DELETE CASCADE, FOREIGN KEY (order_item_id) REFERENCES order_items(id) ON DELETE SET NULL, FOREIGN KEY (menu_item_id) REFERENCES menu_items(id) ON DELETE SET NULL);
CREATE TABLE pos_payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restaurant_id BIGINT UNSIGNED NOT NULL, invoice_id BIGINT UNSIGNED NOT NULL, method ENUM('CASH','CARD','BANK_TRANSFER','ONLINE_PAYMENT','OTHER') NOT NULL, amount DECIMAL(12,2) NOT NULL, amount_received DECIMAL(12,2) NULL, reference VARCHAR(120) NULL, notes VARCHAR(500) NULL, idempotency_key CHAR(64) NULL, recorded_by BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, UNIQUE KEY uq_pos_payment_retry (restaurant_id,idempotency_key), KEY idx_pos_payment_tenant_date (restaurant_id,created_at), FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE, FOREIGN KEY (invoice_id) REFERENCES pos_invoices(id) ON DELETE CASCADE, FOREIGN KEY (recorded_by) REFERENCES users(id) ON DELETE RESTRICT);
CREATE TABLE pos_invoice_tips (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restaurant_id BIGINT UNSIGNED NOT NULL, invoice_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(12,2) NOT NULL DEFAULT 0, updated_by BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY uq_pos_invoice_tip (restaurant_id,invoice_id), KEY idx_pos_tip_tenant_date (restaurant_id,updated_at), FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE, FOREIGN KEY (invoice_id) REFERENCES pos_invoices(id) ON DELETE CASCADE, FOREIGN KEY (updated_by) REFERENCES users(id) ON DELETE RESTRICT);
CREATE TABLE pos_kots (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restaurant_id BIGINT UNSIGNED NOT NULL, order_id BIGINT UNSIGNED NOT NULL, kot_number VARCHAR(40) NOT NULL, created_by BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, UNIQUE KEY uq_pos_kot_number (restaurant_id,kot_number), KEY idx_pos_kot_order (restaurant_id,order_id), FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE, FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE RESTRICT);
CREATE TABLE pos_kot_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, kot_id BIGINT UNSIGNED NOT NULL, order_item_id BIGINT UNSIGNED NULL, item_name VARCHAR(150) NOT NULL, portion VARCHAR(50) NULL, quantity INT NOT NULL, action ENUM('ADDED','CANCELLED') NOT NULL, special_instruction VARCHAR(500) NULL, FOREIGN KEY (kot_id) REFERENCES pos_kots(id) ON DELETE CASCADE, FOREIGN KEY (order_item_id) REFERENCES order_items(id) ON DELETE SET NULL);
CREATE TABLE pos_bill_edit_audit (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restaurant_id BIGINT UNSIGNED NOT NULL, order_id BIGINT UNSIGNED NOT NULL, invoice_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, user_name VARCHAR(120) NOT NULL, user_role VARCHAR(30) NOT NULL, action_type VARCHAR(40) NOT NULL, item_id BIGINT UNSIGNED NULL, previous_value TEXT NULL, new_value TEXT NULL, reason VARCHAR(500) NULL, ip_address VARCHAR(45) NULL, created_at DATETIME NOT NULL, KEY idx_pos_audit_invoice (restaurant_id,invoice_id,id), FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE, FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY (invoice_id) REFERENCES pos_invoices(id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE RESTRICT);
CREATE TABLE pos_delivery_status_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restaurant_id BIGINT UNSIGNED NOT NULL, order_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, previous_status VARCHAR(30) NOT NULL, new_status VARCHAR(30) NOT NULL, created_at DATETIME NOT NULL, KEY idx_pos_delivery_order (restaurant_id,order_id,id), FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE, FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE RESTRICT);
CREATE TABLE subscription_payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restaurant_id BIGINT UNSIGNED NOT NULL, subscription_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(12,2) NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'LKR', paid_on DATE NOT NULL, method VARCHAR(60) NULL, reference VARCHAR(120) NULL, notes VARCHAR(500) NULL, created_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE, FOREIGN KEY (subscription_id) REFERENCES subscriptions(id) ON DELETE CASCADE, FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE RESTRICT, INDEX(restaurant_id,paid_on));
CREATE TABLE login_attempts (bucket CHAR(64) NOT NULL PRIMARY KEY, attempts INT UNSIGNED NOT NULL DEFAULT 0, window_started DATETIME NOT NULL, INDEX(window_started));
CREATE TABLE order_status_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restaurant_id BIGINT UNSIGNED NOT NULL, order_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NULL, previous_status VARCHAR(20) NOT NULL, new_status VARCHAR(20) NOT NULL, created_at DATETIME NOT NULL, INDEX(restaurant_id,order_id,id), FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE, FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE menu_availability_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restaurant_id BIGINT UNSIGNED NOT NULL, menu_item_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NULL, previous_available TINYINT NOT NULL, new_available TINYINT NOT NULL, created_at DATETIME NOT NULL, INDEX(restaurant_id,menu_item_id,id), FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE, FOREIGN KEY (menu_item_id) REFERENCES menu_items(id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL);
